import os,json,subprocess
from pathlib import Path
old=Path("/var/www/fadego-preview")
new=Path("/srv/projects/fadego/www/preview")
conf=Path("/etc/nginx/sites-available/fadego-staging.conf")
out={"project":"fadego","status":"BLOCKED","alias_removed":False}
def cmd(args):
 return subprocess.run(args,capture_output=True,text=True,timeout=10).returncode
def states():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in ("ssh","nginx","fadego-staging","lowcost-europa","pink-iptv-backend","pm2-root")}
deleted=False
try:
 if not old.is_symlink() or old.resolve(strict=True)!=new or not new.is_dir() or new.is_symlink():raise RuntimeError("alias_or_target_identity")
 s=conf.read_text()
 if "/var/www/fadego-preview" in s or s.count(str(new))!=1 or cmd(["nginx","-t"]):raise RuntimeError("nginx_canonical_precondition")
 if cmd(["runuser","-u","www-data","--","test","-r",str(new/"index.html")]):raise RuntimeError("www_data_postcutover_access")
 before=states()
 os.unlink(old);deleted=True
 if old.exists() or old.is_symlink() or cmd(["nginx","-t"]) or states()!=before:raise RuntimeError("post_unlink_health_changed")
 out.update(status="ALIAS_REMOVED_VERIFIED",alias_removed=True,canonical=str(new),nginx_valid=True,services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:150]
 if deleted and not old.exists() and not old.is_symlink():
  try:os.symlink(str(new),old);out["rollback"]="RESTORED_ALIAS"
  except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="ALIAS_REMOVED_VERIFIED":raise SystemExit(3)
